def count_exact(s,L):
    idx={}
    for i in range(len(s)-L+1):
        idx.setdefault(s[i:i+L],[]).append(i)
    c=0
    for w,ps in idx.items():
        rw=rc(w)
        if rw in idx:
            for i in ps:
                for j in idx[rw]:
                    if j>=i+L: c+=1
    return c

